// Generates the default 1-tap buttons and countable denominations for both apps from spec/presets.json.
//   -> ios/Shared/Core/DefaultPresets.swift
//   -> android/core/src/main/kotlin/com/patternsystems/pocketcash/core/DefaultPresets.kt
//   -> site/presets.js (the preview site's demo)
// Usage: node tools/build_presets.js           (write the files)
//        node tools/build_presets.js --check   (CI: fail when a generated file is out of date)
// No dependencies.
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const spec = JSON.parse(fs.readFileSync(path.join(ROOT, 'spec', 'presets.json'), 'utf8'));
const check = process.argv.includes('--check');

const codes = Object.keys(spec.currencies).sort();
for (const code of codes) {
  if (!/^[A-Z]{3}$/.test(code)) throw new Error(`presets.json: "${code}" isn't an ISO 4217 code`);
  const p = spec.currencies[code];
  for (const key of ['add', 'spend', 'denominations']) {
    if (!Array.isArray(p[key]) || !p[key].length || p[key].some(v => typeof v !== 'number' || !(v > 0))) {
      throw new Error(`presets.json: ${code}.${key} must be a non-empty list of positive numbers`);
    }
  }
  if (p.add.length > 2) throw new Error(`presets.json: ${code}.add has more than 2 buttons`);
  if (p.spend.length > 4) throw new Error(`presets.json: ${code}.spend has more than 4 buttons`);
}

const num = v => String(v);
const header = 'Generated by tools/build_presets.js from spec/presets.json. Do not edit: change the JSON and run the tool.';

function swift() {
  const list = vs => `[${vs.map(v => `d("${num(v)}")`).join(', ')}]`;
  const entry = p => `CurrencyPresets(add: ${list(p.add)}, spend: ${list(p.spend)}, denominations: ${list(p.denominations)})`;
  return [
    `// ${header}`,
    'import Foundation',
    '',
    '/// Default buttons and countable bills/coins for one currency (docs/spec.md section 2).',
    'public struct CurrencyPresets: Sendable, Equatable {',
    '    /// Cash-in buttons; the first is the widget\'s + button.',
    '    public let add: [Decimal]',
    '    /// Spend buttons (positive magnitudes) in widget order.',
    '    public let spend: [Decimal]',
    '    /// What "Count my cash" offers, largest first.',
    '    public let denominations: [Decimal]',
    '',
    '    public init(add: [Decimal], spend: [Decimal], denominations: [Decimal]) {',
    '        self.add = add',
    '        self.spend = spend',
    '        self.denominations = denominations',
    '    }',
    '}',
    '',
    'public enum DefaultPresets {',
    `    public static let fallback = ${entry(spec.default)}`,
    '',
    '    public static let table: [String: CurrencyPresets] = [',
    ...codes.map(c => `        "${c}": ${entry(spec.currencies[c])},`),
    '    ]',
    '',
    '    public static func forCurrency(_ code: String) -> CurrencyPresets {',
    '        table[code.uppercased()] ?? fallback',
    '    }',
    '',
    '    private static func d(_ s: String) -> Decimal {',
    '        Decimal(string: s, locale: Locale(identifier: "en_US_POSIX")) ?? 0',
    '    }',
    '}',
    '',
  ].join('\n');
}

function kotlin() {
  const list = vs => `listOf(${vs.map(v => `"${num(v)}"`).join(', ')})`;
  const entry = p => `p(${list(p.add)}, ${list(p.spend)}, ${list(p.denominations)})`;
  return [
    `// ${header}`,
    'package com.patternsystems.pocketcash.core',
    '',
    'import java.math.BigDecimal',
    '',
    '/** Default buttons and countable bills/coins for one currency (docs/spec.md section 2). */',
    'data class CurrencyPresets(',
    '    /** Cash-in buttons; the first is the widget\'s + button. */',
    '    val add: List<BigDecimal>,',
    '    /** Spend buttons (positive magnitudes) in widget order. */',
    '    val spend: List<BigDecimal>,',
    '    /** What "Count my cash" offers, largest first. */',
    '    val denominations: List<BigDecimal>,',
    ')',
    '',
    'object DefaultPresets {',
    `    val fallback: CurrencyPresets = ${entry(spec.default)}`,
    '',
    '    val table: Map<String, CurrencyPresets> = mapOf(',
    ...codes.map(c => `        "${c}" to ${entry(spec.currencies[c])},`),
    '    )',
    '',
    '    fun forCurrency(code: String): CurrencyPresets = table[code.uppercase()] ?: fallback',
    '',
    '    private fun p(add: List<String>, spend: List<String>, denominations: List<String>) =',
    '        CurrencyPresets(add.map(::BigDecimal), spend.map(::BigDecimal), denominations.map(::BigDecimal))',
    '}',
    '',
  ].join('\n');
}

function site() {
  const entry = p => JSON.stringify({ add: p.add, spend: p.spend, denominations: p.denominations });
  return [
    `// ${header}`,
    'window.POCKETCASH_PRESETS = {',
    `  default: ${entry(spec.default)},`,
    '  currencies: {',
    ...codes.map(c => `    ${c}: ${entry(spec.currencies[c])},`),
    '  },',
    '};',
    '',
  ].join('\n');
}

const outputs = [
  ['ios/Shared/Core/DefaultPresets.swift', swift()],
  ['android/core/src/main/kotlin/com/patternsystems/pocketcash/core/DefaultPresets.kt', kotlin()],
  ['site/presets.js', site()],
];

let stale = 0;
for (const [rel, text] of outputs) {
  const file = path.join(ROOT, rel);
  if (check) {
    const current = fs.existsSync(file) ? fs.readFileSync(file, 'utf8').replace(/\r\n/g, '\n') : null;
    if (current !== text) { console.error(`${rel} is out of date: run node tools/build_presets.js`); stale++; }
    continue;
  }
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, text);
  console.log(`wrote ${rel} (${codes.length} currencies + default)`);
}
if (stale) process.exit(1);
